  uint64_t t = fetch_and_add(&r->tail, 1);
  Slot *s = &r->slots[t & (N-1)];
  memcpy(s->payload, payload, 64);
  __sync_synchronize(); // fence before seq
  s->seq = t<<1 | 1; // mark committed
